// Transport-specific marker-driven typesupport TU fragment for a dds rpc_client.
// Auto-generated by ibmw_gen as an RPC client typesupport sidecar.

namespace dds_rpc_demo {

template <typename SelfT>
inline ibmw::co::Task<void> _ibmw_dds_rpc_client_loop_body_impl_rpc_client_module(SelfT* self) {
  try {
    MW_INFO("Start RPC loop.");

    uint32_t counter = 0;
    while (self->ctx_ptr_->Running()) {
      self->ctx_ptr_->LetMe();

      // --- Call AddTwoInts ---
      {
        dds_rpc_demo::AddTwoInts_Request req;
        dds_rpc_demo::AddTwoInts_Response rsp;
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_ADD_TWO_INTS_BEGIN
        req.a(static_cast<int64_t>(counter));
        req.b(static_cast<int64_t>(counter) * 10);
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_ADD_TWO_INTS_END

        auto status = co_await self->client_.AddTwoInts.Call(req, rsp);
        self->ctx_ptr_->LetMe();

        if (status.OK()) {
          (void)rsp;
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_ADD_TWO_INTS_BEGIN
          MW_INFO("AddTwoInts OK: {} + {} = {}", req.a(), req.b(), rsp.sum());
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_ADD_TWO_INTS_END
        }

        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_ADD_TWO_INTS_BEGIN
        if (!status.OK()) {
          MW_WARN("AddTwoInts FAILED: {}", status.ToString());
        }
        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_ADD_TWO_INTS_END
      }

      ++counter;

      // Wait 2 seconds before next round
      co_await ibmw::co::ScheduleAfter(
          ibmw::co::IbmwExecutor(self->time_executor_),
          std::chrono::seconds(2));
    }

    MW_INFO("Exit RPC loop.");
  } catch (const std::exception& e) {
    MW_ERROR("RpcLoop failed: {}", e.what());
  }

  co_return;
}

}  // namespace dds_rpc_demo
